p=root/'docs/research/UFUK-width-opening-splits-20261004.json';assert not p.exists();p.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'roots':len(rows),'prior_arena_files_checked':arenas}))

